return [
  {
    json: {
      batch_size: 10,
      delay_ms: 2000,
      retry_attempts: 3,
      retry_delay_ms: 5000,
    },
  },
];

const sentItems = $('Send Telegram Batch').all();

const sentByVacancyId = new Map(
  sentItems.map((item) => {
    const vacancyId = String(
      item.json.vacancy_id || ''
    );

    return [
      vacancyId,
      item.json,
    ];
  })
);

return $input.all().map((item) => {
  const updatedRow = item.json;

  const vacancyId = String(
    updatedRow.vacancy_id || ''
  );

  const sendResult =
    sentByVacancyId.get(vacancyId) ||
    updatedRow;

  return {
    json: {
      vacancy_id: vacancyId,
      title: String(
        updatedRow.title ||
        sendResult.title ||
        ''
      ),
      company: String(
        updatedRow.company ||
        sendResult.company ||
        ''
      ),
      previous_status: String(
        sendResult.telegram_previous_status ||
        ''
      ),
      status: String(
        updatedRow.status ||
        sendResult.status ||
        ''
      ),
      telegram_message_id: String(
        updatedRow.telegram_message_id ||
        sendResult.telegram_message_id ||
        ''
      ),
      send_success:
        sendResult.telegram_send_success === true,
      last_error: String(
        updatedRow.last_error ||
        sendResult.last_error ||
        ''
      ),
      url: String(
        updatedRow.url ||
        sendResult.url ||
        ''
      ),
    },
  };
});

const settings = $('Telegram Settings').first().json;

const batchSize = Math.max(
  1,
  Math.min(100, Number(settings.batch_size || 10))
);

const delayMs = Math.max(
  1000,
  Number(settings.delay_ms || 2000)
);

const retryAttempts = Math.max(
  1,
  Math.min(5, Number(settings.retry_attempts || 3))
);

const retryDelayMs = Math.max(
  1000,
  Number(settings.retry_delay_ms || 5000)
);

const token = String($env.PANEVIN_BOT || '').trim();
const adminId = String(
  $env.PANEVIN_ADMIN_ID || '401063682'
).trim();

if (!token) {
  throw new Error('PANEVIN_BOT is empty');
}

if (!adminId) {
  throw new Error('PANEVIN_ADMIN_ID is empty');
}

const allowedStatuses = new Set([
  'letter_ready',
  'letter_review',
]);

const queueLabels = {
  letter_ready: 'ГОТОВО К ОТКЛИКУ',
  letter_review: 'ТРЕБУЕТ ПРОВЕРКИ',
};

const queuePriority = {
  letter_ready: 0,
  letter_review: 1,
};

const resumeNames = {
  ai_automation: 'Инженер по автоматизации и AI-интеграциям',
  it_infrastructure: 'IT-инженер / системный администратор',
};

function sleep(milliseconds) {
  return new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });
}

function parseObject(value) {
  if (value && typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string' || !value.trim()) {
    return {};
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

function clean(value) {
  return String(value || '')
    .replace(/\u00a0/g, ' ')
    .replace(/[\u2013\u2014\u2212]/g, '-')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/\u2022/g, '-')
    .replace(/\u2192/g, '->')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function sanitizeError(error) {
  return String(
    error?.message ||
    error ||
    'Unknown Telegram error'
  )
    .split(token)
    .join('[REDACTED_BOT_TOKEN]')
    .slice(0, 1500);
}

function getVacancyMetadata(vacancy) {
  const analysis = parseObject(vacancy.analysis_json);

  const evaluation =
    analysis.evaluation &&
    typeof analysis.evaluation === 'object'
      ? analysis.evaluation
      : analysis;

  const generation =
    analysis.cover_letter_generation &&
    typeof analysis.cover_letter_generation === 'object'
      ? analysis.cover_letter_generation
      : {};

  const score = Number.isFinite(Number(vacancy.score))
    ? Number(vacancy.score)
    : Number(evaluation.score || 0);

  const decision = String(
    evaluation.decision ||
    (
      score >= 75
        ? 'recommend'
        : score >= 60
          ? 'review'
          : 'reject'
    )
  );

  const warnings = Array.isArray(generation.warnings)
    ? generation.warnings
        .map(clean)
        .filter(Boolean)
        .slice(0, 5)
    : [];

  return {
    score,
    decision,
    warnings,
  };
}

function buildTelegramHtml(vacancy, metadata) {
  const status = String(vacancy.status || '').trim();
  const resumeKey = String(
    vacancy.recommended_resume || ''
  ).trim();

  const resumeName = resumeNames[resumeKey];

  if (!resumeName) {
    throw new Error(
      `Unknown recommended_resume "${resumeKey}" for vacancy ${
        vacancy.vacancy_id || 'unknown'
      }`
    );
  }

  const queueLabel = queueLabels[status];

  if (!queueLabel) {
    throw new Error(
      `Unsupported Telegram queue status "${status}" for vacancy ${
        vacancy.vacancy_id || 'unknown'
      }`
    );
  }

  const warnings = metadata.warnings;

  const warningBlock = warnings.length > 0
    ? [
        '',
        '<b>ПРЕДУПРЕЖДЕНИЯ:</b>',
        ...warnings.map(
          (warning) => `- ${escapeHtml(warning)}`
        ),
      ]
    : [];

  const reviewNotice = status === 'letter_review'
    ? [
        '',
        '<b>ПРОВЕРЬ ПИСЬМО ПЕРЕД ОТКЛИКОМ</b>',
      ]
    : [];

  const coverLetter = clean(vacancy.cover_letter);

  if (!coverLetter) {
    throw new Error(
      `Cover letter is empty for vacancy ${
        vacancy.vacancy_id || 'unknown'
      }`
    );
  }

  const plainLengthCheck = [
    queueLabel,
    vacancy.title,
    vacancy.company,
    resumeName,
    vacancy.salary,
    vacancy.location,
    vacancy.work_format,
    vacancy.url,
    coverLetter,
    ...warnings,
  ].join('\n');

  if (plainLengthCheck.length > 3900) {
    throw new Error(
      `Telegram message is too long for vacancy ${
        vacancy.vacancy_id || 'unknown'
      }: ${plainLengthCheck.length} characters`
    );
  }

  return [
    `<b>${escapeHtml(queueLabel)}</b>`,
    '',
    `<b>${escapeHtml(clean(vacancy.title))}</b>`,
    escapeHtml(clean(vacancy.company)),
    '',
    `Score: ${metadata.score}`,
    `Decision: ${escapeHtml(metadata.decision)}`,
    `Резюме: ${escapeHtml(resumeName)}`,
    `Зарплата: ${escapeHtml(clean(vacancy.salary || 'не указана'))}`,
    `Локация: ${escapeHtml(clean(vacancy.location || 'не указана'))}`,
    `Формат: ${escapeHtml(clean(vacancy.work_format || 'unspecified'))}`,
    ...reviewNotice,
    ...warningBlock,
    '',
    `Вакансия: ${escapeHtml(clean(vacancy.url))}`,
    '',
    '<b>СОПРОВОДИТЕЛЬНОЕ ПИСЬМО:</b>',
    `<pre>${escapeHtml(coverLetter)}</pre>`,
  ].join('\n');
}

async function sendTelegramMessage(telegramHtml) {
  let lastError;

  for (
    let attempt = 1;
    attempt <= retryAttempts;
    attempt += 1
  ) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://api.telegram.org/bot${token}/sendMessage`,
        headers: {
          'Content-Type': 'application/json',
        },
        body: {
          chat_id: adminId,
          text: telegramHtml,
          parse_mode: 'HTML',
          link_preview_options: {
            is_disabled: true,
          },
        },
        json: true,
      });

      if (!response?.ok || !response?.result?.message_id) {
        throw new Error(
          `Unexpected Telegram response: ${JSON.stringify(response)}`
        );
      }

      return response.result;
    } catch (error) {
      lastError = error;

      if (attempt < retryAttempts) {
        await sleep(retryDelayMs);
      }
    }
  }

  throw lastError;
}

const rows = $input.all()
  .map((item) => {
    const vacancy = { ...item.json };
    const metadata = getVacancyMetadata(vacancy);

    return {
      vacancy,
      metadata,
    };
  })
  .filter(({ vacancy }) => {
    const status = String(vacancy.status || '').trim();

    return (
      allowedStatuses.has(status) &&
      typeof vacancy.cover_letter === 'string' &&
      vacancy.cover_letter.trim() &&
      !String(vacancy.telegram_message_id || '').trim()
    );
  })
  .sort((a, b) => {
    const aStatus = String(a.vacancy.status || '');
    const bStatus = String(b.vacancy.status || '');

    const statusDifference =
      (queuePriority[aStatus] ?? 99) -
      (queuePriority[bStatus] ?? 99);

    if (statusDifference !== 0) {
      return statusDifference;
    }

    if (b.metadata.score !== a.metadata.score) {
      return b.metadata.score - a.metadata.score;
    }

    return String(
      b.vacancy.published_at || ''
    ).localeCompare(
      String(a.vacancy.published_at || '')
    );
  })
  .slice(0, batchSize);

const results = [];

for (let index = 0; index < rows.length; index += 1) {
  const { vacancy, metadata } = rows[index];

  const previousStatus = String(
    vacancy.status || ''
  ).trim();

  if (index > 0) {
    await sleep(delayMs);
  }

  try {
    const telegramHtml = buildTelegramHtml(
      vacancy,
      metadata
    );

    const telegramResponse =
      await sendTelegramMessage.call(
        this,
        telegramHtml
      );

    results.push({
      json: {
        ...vacancy,
        telegram_previous_status: previousStatus,
        telegram_message_id: String(
          telegramResponse.message_id
        ),
        status: 'sent_to_telegram',
        updated_at: new Date().toISOString(),
        last_error: '',
        telegram_send_success: true,
      },
    });
  } catch (error) {
    const safeMessage = sanitizeError(error);

    results.push({
      json: {
        ...vacancy,
        telegram_previous_status: previousStatus,
        status: previousStatus,
        updated_at: new Date().toISOString(),
        last_error: `Telegram send failed: ${safeMessage}`,
        telegram_send_success: false,
      },
    });
  }
}

return results;
